window.BOOK={"key":"bayquniyya","app":"mutoon-bayquniyya","lsk":"mutoon_bayquniyya_v1","prefix":"ba_","title":"المنظومة البيقونية","sub":"في مصطلح الحديث · عمر بن محمد البيقوني · ٣٤ بيتًا","poems":[{"id":"bayquniyya","title":"المنظومة البيقونية","nazim":"عمر (أو طه) بن محمد البيقوني","death":"ت نحو ١٠٨٠هـ","meter":"الرجز","source":"الألوكة، مقابلًا بالشاملة و«الجامع للمتون العلمية» ونسخة محققة","srcUrl":"https://www.alukah.net/sharia/0/123682","note":"آخر بيت على القراءة المشهورة «أبياتها ثم بخير ختمت»، وفي نسخ «أقسامها تمّت بخير ختمت».","verses":[["أَبْدَأُ بِالحَمْدِ مُصَلِّيًا عَلَى","مُحَمَّدٍ خَيْرِ نَبِيٍّ أُرْسِلاَ"],["وَذِي مِنَ اقْسَامِ الحَدِيثِ عِدَّهْ","وَكُلُّ وَاحِدٍ أَتَى وَحَدَّهْ"],["أَوَّلُهَا الصَّحِيحُ وَهْوَ مَا اتَّصَلْ","إسْنَادُهُ وَلَمْ يَشُذَّ أَوْ يُعَلّْ"],["يَرْوِيهِ عَدْلٌ ضَابِطٌ عَنْ مِثْلِهِ","مُعْتَمَدٌ فِي ضَبْطِهِ وَنَقْلِهِ"],["وَالْحَسَنُ المَعْرُوفُ طُرْقًا وَغَدَتْ","رِجَالُهُ لاَ كَالصَّحِيحِ اشْتَهَرَتْ"],["وَكُلُّ مَا عَنْ رُتْبَةِ الْحُسْنِ قَصُرْ","فَهْوَ الضَّعِيفُ وَهْوَ أَقْسَامًا كَثُرْ"],["وَمَا أُضِيفَ لِلنَّبِي المَرْفُوعُ","وَمَا لِتَابِعٍ هُوَ المَقْطُوعُ"],["وَالْمُسْنَدُ الْمُتَّصِلُ الْإِسْنَادِ مِنْ","رَاوِيهِ حَتَّى الْمُصْطَفَى وَلَمْ يَبِنْ"],["وَمَا بِسَمْعِ كُلِّ رَاوٍ يَتَّصِلْ","إِسْنَادُهُ لِلْمُصْطَفَى فَالْمُتَّصِلْ"],["مُسَلْسَلٌ قُلْ مَا عَلَى وَصْفٍ أَتَى","مِثْلُ أَمَا وَاللَّهِ أَنْبَانِي الْفَتَى"],["كَذَاكَ قَدْ حَدَّثَنِيهِ قَائِمَا","أَوْ بَعْدَ أَنْ حَدَّثَنِي تَبَسَّمَا"],["عَزِيزُ مَرْوِي اثْنَيْنِ أَوْ ثَلاَثَهْ","مَشْهُورُ مَرْوِي فَوْقَ مَا ثَلاَثَهْ"],["مُعَنْعَنٌ كَعَنْ سَعِيدٍ عَنْ كَرَمْ","وَمُبْهَمٌ مَا فِيهِ رَاوٍ لَمْ يُسَمّْ"],["وَكُلُّ مَا قَلَّتْ رِجَالُهُ عَلاَ","وَضِدُّهُ ذَاكَ الَّذِي قَدْ نَزَلاَ"],["وَمَا أَضَفْتَهُ إِلَى الْأَصْحَابِ مِنْ","قَوْلٍ وَفِعْلٍ فَهْوَ مَوْقُوفٌ زُكِنْ"],["وَمُرْسَلٌ مِنْهُ الصَّحَابِيُّ سَقَطْ","وَقُلْ غَرِيبٌ مَا رَوَى رَاوٍ فَقَطْ"],["وَكُلُّ مَا لَمْ يَتَّصِلْ بِحَالِ","إِسْنَادُهُ مُنْقَطِعُ الْأَوْصَالِ"],["وَالْمُعْضَلُ السَّاقِطُ مِنْهُ اثْنَانِ","وَمَا أَتَى مُدَلَّسًا نَوْعَانِ"],["الْأَوَّلُ الْإِسْقَاطُ لِلشَّيْخِ وَأَنْ","يَنْقُلَ عَمَّنْ فَوْقَهُ بِعَنْ وَأَنْ"],["وَالثَّانِ لاَ يُسْقِطُهُ لَكِنْ يَصِفْ","أَوْصَافَهُ بِمَا بِهِ لاَ يَنْعَرِفْ"],["وَمَا يُخَالِفْ ثِقَةٌ بِهِ الْمَلاَ","فَالشَّاذُ والْمَقْلُوبُ قِسْمَانِ تَلاَ"],["إِبْدَالُ رَاوٍ مَا بِرَاوٍ قِسْمُ","وَقَلْبُ إِسْنَادٍ لِمَتْنٍ قِسْمُ"],["وَالْفَرْدُ مَا قَيَّدْتَهُ بِثِقَةِ","أَوْ جَمْعٍ اوْ قَصْرٍ عَلَى رِوَايَةِ"],["وَمَا بِعِلَّةٍ غُمُوضٍ اوْ خَفَا","مُعَلَّلٌ عِنْدَهُمُ قدْ عُرِفَا"],["وَذُو اخْتِلاَفِ سَنَدٍ أَوْ مَتْنِ","مُضْطَرِبٌ عِنْدَ أُهَيْلِ الْفَنِّ"],["وَالْمُدْرَجَاتُ فِي الحَدِيثِ مَا أَتَتْ","مِنْ بَعْضِ أَلْفَاظِ الرُّوَاةِ اتَّصَلَتْ"],["وَمَا رَوَى كُلُّ قَرِينٍ عَنْ أَخِهْ","مُدَبَّجٌ فَاعْرِفْهُ حَقًّا وَانْتَخِهْ"],["مُتَّفِقٌ لَفْظًا وَخَطًّا مُتَّفِقْ","وَضِدُّهُ فِيمَا ذَكَرْنَا الْمُفْتَرِقْ"],["مُؤْتَلِفٌ مُتَّفِقُ الخَطِّ فَقَطْ","وَضِدُّهُ مُخْتَلِفٌ فَاخْشَ الْغَلَطْ"],["وَالْمُنْكَرُ الْفَرْدُ بِهِ رَاوٍ غَدَا","تَعْدِيلُهُ لاَ يَحْمِلُ التَّفَرُّدَا"],["مَتْرُوكُهُ مَا وَاحِدٌ بِهِ انْفَرَدْ","وَأَجْمَعُوا لِضَعْفِهِ فَهْوَ كَرَدّْ"],["وَالْكَذِبُ الْمُخْتَلَقُ الْمَصْنُوعُ","عَلَى النَّبِي فَذَلِكَ الْمَوْضُوعُ"],["وَقَدْ أَتَتْ كَالْجَوْهَرِ الْمَكْنُونِ","سَمَّيْتُهَا مَنْظُومَةَ الْبَيْقُونِي"],["فَوْقَ الثَّلَاثِينَ بِأَرْبَعٍ أَتَتْ","أَبْيَاتُهَا ثُمَّ بِخَيْرٍ خُتِمَتْ"]],"secs":{"1":"المنظومة"}}]};
